"""Invariant fuzzing: structural properties every run must satisfy."""
import json, random, subprocess, sys
sys.path.insert(0, '/workspace/tests')
from harness import run, prof, query, rec, Checks

c = Checks()
PAIRS = {('SERVFAIL', 'LOOP'), ('REFUSED', 'OUTSIDE'), ('NOERROR', 'EXTERNAL'),
         ('NXDOMAIN', 'NXDOMAIN'), ('NOERROR', 'ANSWER'), ('NOERROR', 'NODATA'),
         ('NOERROR', 'CNAME_STOP'), ('SERVFAIL', 'LIMIT')}

LABELS = ['a', 'b', 'c', 'x', 'y', 'z', 'w', 'q']
BASES = ['.', 't.', 's.t.', 'u.s.t.', 'v.u.s.t.', 'e.t.', 'o.s.t.']
TARGETS = ['end.t.', 'k.s.t.', 'nope.example.', 't.', 'a.t.', '.', 'b.v.u.s.t.']

def join(chain, base):
    if not chain and base == '.':
        return '.'
    if not chain:
        return base
    if base == '.':
        return chain + '.'
    return chain + '.' + base

def make_doc(rng):
    origins = rng.sample(sorted(set(BASES)), rng.randint(0, 4))
    zones = []
    for origin in origins:
        recs, seen = [], {}
        for _ in range(rng.randint(0, 6)):
            if origin == '.' and rng.random() < 0.2:
                owner = '*.'
            elif rng.random() < 0.18:
                owner = join('*', origin)
            else:
                owner = join('.'.join(rng.choice(LABELS) for _ in range(rng.randint(1, 3))), origin)
            if owner == origin or owner in seen:
                continue
            if rng.random() < 0.35:
                seen[owner] = 'CNAME'
                recs.append(rec(owner, 'CNAME', rng.choice(TARGETS)))
            else:
                rtype = rng.choice(['A', 'AAAA', 'TXT'])
                seen[owner] = rtype
                for _ in range(rng.randint(1, 3)):
                    if rtype == 'A':
                        recs.append(rec(owner, 'A', '192.0.2.%d' % rng.randint(0, 255)))
                    elif rtype == 'AAAA':
                        recs.append(rec(owner, 'AAAA', '198.51.100:%x' % 0 if False else '2001:db8::%x' % rng.randint(0, 255)))
                    else:
                        recs.append(rec(owner, 'TXT', rng.choice(['u', 'v', 'w', 'x'])))
        zones.append({'origin': origin, 'records': recs})
    profiles = [prof('p%d' % i, rng.choice([0, 1, 2, 3, 4, 5, 64]),
                     rng.choice(['follow', 'stop']), rng.choice(['rfc', 'off', 'one-label']))
                for i in range(rng.randint(1, 8))]
    queries = []
    for qi in range(rng.randint(0, 20)):
        chain = '.'.join(rng.choice(LABELS) for _ in range(rng.randint(0, 3)))
        if rng.random() < 0.12:
            chain = ('*.' + chain) if chain else '*'
        name = join(chain, rng.choice(BASES))
        queries.append(query('q%02d' % qi, name, rng.choice(['A', 'AAAA', 'TXT', 'CNAME']),
                             rng.randint(1, 1000)))
    observations = []
    for oi in range(rng.randint(0, 8)):
        q = rng.choice(queries) if queries else None
        if q is None:
            break
        if rng.random() < 0.3:
            result = {'status': 'timeout'}
        else:
            result = {'status': 'response', 'rcode': rng.choice(
                ['NOERROR', 'NXDOMAIN', 'SERVFAIL', 'REFUSED']),
                'answer': [rec('n%d.t.' % j, 'A', '192.0.2.%d' % j) for j in range(rng.randint(0, 4))]}
        observations.append({'id': 'o%02d' % oi, 'query': q['id'],
                            'profile': rng.choice(profiles)['id'], 'result': result})
    return {'zones': zones, 'profiles': profiles, 'queries': queries,
            'observations': observations}

def canon(name):
    return name if name == '.' else name.lower()

def check_invariants(name, doc, out):
    problems = []
    qmap = {q['id']: q for q in doc['queries']}
    pmap = {p['id']: p for p in doc['profiles']}
    runs = out['runs']
    if len(runs) != len(doc['queries']) * len(doc['profiles']):
        problems.append('run count %d' % len(runs))
    expected_order = sorted((q['id'], p['id']) for q in doc['queries'] for p in doc['profiles'])
    if [(r['query'], r['profile']) for r in runs] != expected_order:
        problems.append('run ordering')
    seen_pairs = set()
    for run in runs:
        key = (run['query'], run['profile'])
        if key in seen_pairs:
            problems.append('duplicate run %s' % (key,))
        seen_pairs.add(key)
        q = qmap[run['query']]
        trace = run['trace']
        if not trace:
            problems.append('empty trace')
        if (run['rcode'], run['termination']) not in PAIRS:
            problems.append('bad pair %s' % ((run['rcode'], run['termination']),))
        if trace[0] != canon(q['name']):
            problems.append('trace head %r vs %r' % (trace[0], canon(q['name'])))
        if trace[-1] != run['final_name']:
            problems.append('trace tail %r vs final %r' % (trace[-1], run['final_name']))
        if len(set(trace)) != len(trace) and run['termination'] != 'LOOP':
            problems.append('repeated trace without LOOP: %s %r' % (run['termination'], trace))
        if run['termination'] == 'LOOP':
            if len(trace) < 2 or trace[-1] != trace[-2]:
                problems.append('loop trace tail %r' % (trace,))
        if not run['answer'] and run['answer'] != []:
            problems.append('answer not a list')
        owners = set(trace)
        for record in run['answer']:
            if set(record) != {'owner', 'type', 'data'}:
                problems.append('record keys')
            if record['owner'] not in owners:
                problems.append('answer owner %r not in trace' % record['owner'])
            if record['type'] == 'CNAME' and record['data'] not in owners:
                problems.append('alias target %r not in trace' % record['data'])
            if record['type'] not in ('CNAME', q['type']):
                problems.append('unexpected record type %s' % record['type'])
        if q['type'] != 'CNAME':
            types = [r['type'] for r in run['answer']]
            if types:
                non_cname = [t != 'CNAME' for t in types]
                if any(non_cname[i] and not all(non_cname[i:]) for i in range(len(types))):
                    problems.append('terminal rrset not a suffix: %r' % (types,))
            if run['termination'] == 'ANSWER' and types:
                if types[-1] != q['type'] or run['final_name'] != run['answer'][-1]['owner']:
                    problems.append('terminal rrset mismatch %r %r' % (types[-1], run['final_name']))
        if run['termination'] == 'NODATA':
            if run['answer'] and run['answer'][-1]['type'] != 'CNAME':
                problems.append('NODATA terminal record not CNAME')
        if run['termination'] == 'LIMIT' and run['answer'] and run['answer'][-1]['owner'] != run['final_name']:
            problems.append('LIMIT last alias owner %r vs final %r'
                            % (run['answer'][-1]['owner'], run['final_name']))
        aliases = [p for p in doc['profiles'] if p['id'] == run['profile']][0]
        if run['termination'] == 'LIMIT':
            expected_aliases = aliases['max_aliases']
        else:
            expected_aliases = sum(1 for r in run['answer'] if r['type'] == 'CNAME')
        if aliases['cname'] == 'follow':
            cname_count = sum(1 for r in run['answer'] if r['type'] == 'CNAME')
            if run['termination'] == 'LIMIT':
                if cname_count != aliases['max_aliases']:
                    problems.append('LIMIT with %d cnames, max %d' % (cname_count, aliases['max_aliases']))
            elif cname_count > aliases['max_aliases']:
                problems.append('too many cnames %d > %d' % (cname_count, aliases['max_aliases']))
        if problems:
            c.check(name + ' invariants', False, '; '.join(problems[:6]))
            return False
    return True

seed = int(sys.argv[1]) if len(sys.argv) > 1 else 99
trials = int(sys.argv[2]) if len(sys.argv) > 2 else 400
good = 0
for trial in range(trials):
    rng = random.Random(trial * 6151 + seed)
    doc = make_doc(rng)
    rc, out, err = run(doc)[0], None, None
    p = run(doc)
    if p[0] != 0 or not p[1].startswith(b'{"runs'):
        c.check('fuzz trial %d valid' % trial, False, p[1][:100])
        continue
    parsed = json.loads(p[1])
    if check_invariants('fuzz trial %d' % trial, doc, parsed):
        good += 1
print('invariant fuzz: %d/%d documents exercised' % (good, trials))
sys.exit(c.done('invariant fuzz'))
PYEOF
